import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to the worker that died. Count that interrupted attempt and
// put it back in the durable queue, unless all three attempts were already used.
