db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, available_at=0 WHERE status='running' AND attempts < 3`).run(now);
db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE status='running' AND attempts >= 3`).run(now);
db.exec('COMMIT');

const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(() => { try { heartbeat(); } catch (e) { console.error('heartbeat failed', e); } }, 750);
console.log('worker started');

while (!stopping) {
  heartbeat();
  db.exec('BEGIN IMMEDIATE');
  const row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND available_at <= ? ORDER BY created_at, rowid LIMIT 1`).get(Date.now()) as Record<string, unknown> | undefined;
  if (!row) { db.exec('COMMIT'); await sleep(100); continue; }
  const startedAt = new Date().toISOString();
  db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'`).run(startedAt, String(row.id));
  db.exec('COMMIT');
  const attempt = Number(row.attempts) + 1;
  const steps = Number(row.steps);
  const failAttempts = Number(row.fail_attempts);
  let interrupted = false;
  for (let step = 1; step <= steps; step++) {
    await sleep(100);
    if (stopping) { interrupted = true; break; }
    if (step === 1 && attempt <= failAttempts) {
      const updated = new Date().toISOString();
      if (attempt >= 3) {
        db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=? AND status='running'`).run(updated, String(row.id));
      } else {
        db.prepare(`UPDATE jobs SET status='queued', error=NULL, result_output=NULL, progress_completed=0, updated_at=?, available_at=? WHERE id=? AND status='running'`).run(updated, Date.now() + 500, String(row.id));
